import json,subprocess,sys,time
from playwright.sync_api import sync_playwright
R=lambda **k:{**dict(id=0,date='2026-10-27',time='12:00',place='Копринка',count='',bg='',en='',la='',fam='',note='',h=0,s=1,p=0,beh=[],geo=None,photo=None),**k}
port=int(sys.argv[1]) if len(sys.argv)>1 else 8984;fails=0
def check(n,got,exp):
  global fails;ok=got==exp;fails+=not ok
  print(('PASS ' if ok else 'FAIL ')+n+('' if ok else f'\n     got {got!r}\n     exp {exp!r}'))
srv=subprocess.Popen([sys.executable,'-m','http.server',str(port)],stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL);time.sleep(1)
try:
 with sync_playwright() as p:
  b=p.chromium.launch();ctx=b.new_context(viewport={'width':390,'height':844});ctx.route('https://**',lambda r:r.abort() if 'localhost' not in r.request.url else r.continue_())
  pg=ctx.new_page();errs=[];pg.on('pageerror',lambda e:errs.append(str(e)));pg.on('dialog',lambda d:d.accept())
  pg.add_init_script("if(!localStorage.getItem('bird-journal-v3')){localStorage.setItem('bird-journal-v3',%s);localStorage.setItem('bird-journal-tips','{\"all\":1}');}"%json.dumps(json.dumps([R(id=1,bg='Кос')],ensure_ascii=False)))
  pg.goto(f'http://localhost:{port}/ptichi-dnevnik.html');pg.wait_for_timeout(400)
  pg.click('#toggle');pg.fill('#f-bg','Сива чапля');pg.wait_for_timeout(900)
  check('T1 a misspelt name gets „Имаше ли предвид Сива чапла?“ when you pause typing', (pg.is_visible('#f-typo'),pg.inner_text('#f-typo')), (True,'Имаше ли предвид Сива чапла?'))
  pg.click('#f-typo [data-typo]');pg.wait_for_timeout(100)
  check('T2 ...one tap fixes it and fills in the Latin', (pg.input_value('#f-bg'),pg.input_value('#f-la'),pg.is_visible('#f-typo')), ('Сива чапла','Ardea cinerea',False))
  pg.fill('#f-bg','Сива чапля');pg.click('#f-unsure');pg.wait_for_timeout(900)
  check('T2b moving on quickly: no hint pops up under your finger, and the tap lands where you aimed', (pg.is_visible('#f-typo'),pg.get_attribute('#f-unsure','aria-pressed')), (False,'true'))
  pg.click('#cancel')
  pg.click('#sessStart');pg.fill('#f-bg','Тайнствена птица');pg.click('#savebtn');pg.wait_for_timeout(150)
  pg.fill('#f-bg','Кос');pg.click('#savebtn');pg.wait_for_timeout(150)
  pg.fill('#f-bg','Шарено пиле');pg.click('#savebtn');pg.wait_for_timeout(150);pg.click('#cancel')
  check('T3 a name outside every list saves at once, as typed', pg.evaluate("OBS.filter(o=>o.sess).map(o=>o.bg).sort()"), ['Кос','Тайнствена птица','Шарено пиле'])
  pg.evaluate("yayHide()");pg.click('#sessEnd');pg.wait_for_timeout(100);pg.click('#sess [data-done="1"]');pg.wait_for_timeout(800)
  check('T4 when the outing ends, one dialog asks for the missing names of all such birds', (pg.evaluate("document.getElementById('nnDlg').open"),pg.evaluate("[...document.querySelectorAll('#nn-list .nnr')].map(r=>r.dataset.nnfor).sort()")), (True,['Тайнствена птица','Шарено пиле']))
  pg.click('#nn-later');pg.evaluate("yayHide&&yayHide()");pg.wait_for_timeout(200)
  check('T5 „По-късно“: the records stay, each with a small „допълни имената“ tag', pg.evaluate("[...document.querySelectorAll('#view .tag.nn')].map(t=>t.dataset.nn).sort()"), ['Тайнствена птица','Шарено пиле'])
  pg.locator('#view .tag.nn[data-nn="Тайнствена птица"]').click();pg.wait_for_timeout(150)
  r=pg.locator('#nn-list .nnr').first;r.locator('[data-nnf="la"]').fill('mystica');r.locator('[data-nnf="en"]').fill('Mystery Bird');pg.click('#nn-save');pg.wait_for_timeout(100)
  check('T6 a wrong Latin name is refused, with a hint', ('Род вид' in pg.inner_text('#nn-msg'),pg.evaluate("document.getElementById('nnDlg').open")), (True,True))
  r.locator('[data-nnf="la"]').fill('Avis mystica');pg.click('#nn-save');pg.wait_for_timeout(200)
  check('T7 filled in: the record gets its names, the tag goes, and the bird joins the group\'s list', (pg.evaluate("OBS.find(o=>o.bg==='Тайнствена птица').la"),pg.locator('#view .tag.nn[data-nn="Тайнствена птица"]').count(),pg.evaluate("SPXO.map(x=>x.la)")), ('Avis mystica',0,['Avis mystica']))
  pg.click('#toggle');pg.fill('#f-bg','Тайнствена птица');pg.locator('#f-bg').dispatch_event('change');pg.wait_for_timeout(100)
  check('T8 ...so next time the form fills it in by itself', (pg.input_value('#f-la'),pg.input_value('#f-en')), ('Avis mystica','Mystery Bird'))
  pg.click('#cancel')
  pg.evaluate("OBS.push({id:77,date:today(),time:'09:00',place:'',count:'',bg:'Кус',en:'',la:'',fam:'',note:'',h:0,s:1,p:0,beh:[],geo:null,photo:null});save();render()")
  pg.locator('#view .tag.nn[data-nn="Кус"]').click();pg.wait_for_timeout(150)
  pg.click('#nn-list [data-nnfix]');pg.wait_for_timeout(200)
  check('T9 in the dialog a near miss offers the right bird, and one tap fixes the record', pg.evaluate("[OBS.find(o=>o.id===77).bg,OBS.find(o=>o.id===77).la]"), ['Кос','Turdus merula'])
  pg.click('#toggle');pg.fill('#f-bg','Розово фламинго');pg.fill('#f-la','Phoenicopterus roseus');pg.fill('#f-en','Greater Flamingo');pg.click('#savebtn');pg.wait_for_timeout(200)
  if pg.is_visible('#cancel'):pg.click('#cancel')   # outside an outing the form closes after saving
  check('T10 a new bird saved with all three names joins the group\'s list by itself, no tag', ('Phoenicopterus roseus' in pg.evaluate("SPXO.map(x=>x.la)"),pg.locator('#view .tag.nn[data-nn="Розово фламинго"]').count()), (True,0))
  pg.evaluate("yayHide&&yayHide()")
  pg.click('#acct');pg.wait_for_timeout(150);pg.check('[data-quiet]');pg.click('[data-acctback]');pg.wait_for_timeout(150)
  pg.click('#toggle');pg.fill('#f-bg','Сойка');pg.click('#savebtn');pg.wait_for_timeout(400)
  q1=pg.evaluate("document.getElementById('yay').classList.contains('on')||!!document.getElementById('yay').innerText.trim()&&getComputedStyle(document.getElementById('yay')).display!=='none'")
  pg.is_visible('#cancel') and pg.click('#cancel');pg.click('#acct');pg.wait_for_timeout(150);pg.uncheck('[data-quiet]');pg.click('[data-acctback]')
  pg.click('#toggle');pg.fill('#f-bg','Сврака');pg.click('#savebtn');pg.wait_for_timeout(400)
  check('T11 quiet mode in the profile: no pop-up for a new species; off again, they come back', (q1,'Честито' in pg.evaluate("document.getElementById('yay').innerText")), (False,True))
  check('T12 no page errors', errs, [])
  b.close()
finally: srv.terminate()
print('FAILURES:',fails)
